import{_ as e}from"./chunks/OpenMQTTgateway_M5_Stack_Board_Display_Text.CxNzbM7o.js";import{_ as s,o as r,c as t,a6 as o}from"./chunks/framework.BJFjZBwW.js";const n="/dev/assets/OpenMQTTgateway_M5_Stack_Board_Display_Logo.DmTNZfaz.png",i="/dev/assets/OpenMQTTgateway_M5_Stack_Board_Display_Warning.DjNcJOdU.png",g=JSON.parse('{"title":"M5 Boards","description":"","frontmatter":{},"headers":[],"relativePath":"prerequisites/M5.md","filePath":"prerequisites/M5.md","lastUpdated":1691777092000}'),d={name:"prerequisites/M5.md"};function l(p,a,c,h,m,w){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="m5-boards" tabindex="-1">M5 Boards <a class="header-anchor" href="#m5-boards" aria-label="Permalink to &quot;M5 Boards&quot;">​</a></h1><p>M5 boards, manufactured by <a href="https://m5stack.com/" target="_blank" rel="noreferrer">M5Stack</a> are inexpensive, well featured boards based on ESP32.</p><h2 id="m5stickc-and-m5stack" tabindex="-1">M5StickC and M5Stack <a class="header-anchor" href="#m5stickc-and-m5stack" aria-label="Permalink to &quot;M5StickC and M5Stack&quot;">​</a></h2><p>M5StickC and M5Stack are supported by OpenMQTTGateway and provide the following features:</p><h3 id="_3-low-power-modes" tabindex="-1">3 low power modes <a class="header-anchor" href="#_3-low-power-modes" aria-label="Permalink to &quot;3 low power modes&quot;">​</a></h3><h4 id="always-on-display" tabindex="-1">Always ON display <a class="header-anchor" href="#always-on-display" aria-label="Permalink to &quot;Always ON display&quot;">​</a></h4><p>The display is always ON but decrease its brightness when not processing.</p><h4 id="on-display-when-processing" tabindex="-1">ON display when processing <a class="header-anchor" href="#on-display-when-processing" aria-label="Permalink to &quot;ON display when processing&quot;">​</a></h4><p>The display is OFF when not processing and the ESP32 is put in low power mode.</p><h4 id="always-off-display" tabindex="-1">Always OFF display <a class="header-anchor" href="#always-off-display" aria-label="Permalink to &quot;Always OFF display&quot;">​</a></h4><p>The display is always OFF, if the board has a led, the led is used when processing.</p><p>To change the low power mode you can do it by <a href="./../use/boards.html#low-power-mode-for-m5-boards">MQTT</a> or by pushing the middle button (btn B) of the M5Stack and the top button (btn B) of the M5Stick C</p><h3 id="start-screen" tabindex="-1">Start screen <a class="header-anchor" href="#start-screen" aria-label="Permalink to &quot;Start screen&quot;">​</a></h3><p><img src="'+n+'" alt="MStack core logo"></p><h3 id="sleep-screen" tabindex="-1">Sleep screen <a class="header-anchor" href="#sleep-screen" aria-label="Permalink to &quot;Sleep screen&quot;">​</a></h3><p>The screen brightness is put to a minimum so as to reduce power consumption. <img src="'+e+'" alt="M5Stack core brightness"></p><h3 id="log-display-in-case-of-warning" tabindex="-1">Log display in case of warning <a class="header-anchor" href="#log-display-in-case-of-warning" aria-label="Permalink to &quot;Log display in case of warning&quot;">​</a></h3><p>If the gateway detects a warning or an error the sleep go out the sleep screen and show the message with a red (error) or orange (warning) background. <img src="'+i+'" alt="M5 Stack core warning"></p><p>The M5Stick support low power mode 2 but its display is not supported for the moment.</p>',19)])])}const y=s(d,[["render",l]]);export{g as __pageData,y as default};
